/**
 * @method
 * @name fn_getBzDate
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getBzDate = function() {
    $.ajax({
        type: "POST",
        url: "/digital/ajaxGetCodeData.do",
        data: {
            method: "ajaxGetBzDate",
            expDd: document.getElementById('만기일').getValue()
        },
        async: false,
        success: function(data) {
            result = $.parseJSON(data);
            /*변수명 변경 하지 않고 2일 에서 4일로 변경
              변수명과 실제 일자는 다름
            */
            scwin.date1 = result.minus2BzDate;
            scwin.date2 = result.plus2BzDate;
        },
        error: function(request, status, error) {
            alert("영업일 날짜 조회에 실패했습니다.");
            return;
        },
        complete: function() {
            delay = true;
        }
    });
};




/********************************************** 
 * 함수명   : fn_getCheckByte
 * @param strItemNm - 체크할 항목명
 * @param strVal - 체크할 값
 * @param limitsize - 제한길이
 * 설명       : 제한길이를 체크한다.
 ***********************************************/
/**
 * @method
 * @name fn_getCheckByte
 * @description desc
 * @param {string} inputYn desc
 * @param {string} strItemNm desc
 * @param {string} strVal desc
 * @param {string} limitsize desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getCheckByte = function(inputYn, strItemNm, strVal, limitsize) {
    var len = scwin.fn_getAsciiLength(strVal);
    if (inputYn == 'Y' && len == 0) {
        alert(strItemNm + '값을 입력해주세요.');
        return false;
    }
    if (limitsize < len) {
        alert('입력된 [' + strItemNm + ']은 ' + len + 'Byte로 \n제한 길이인 ' + limitsize + 'Byte를 초과 하였습니다.');
        return false;
    }
    return true;
};
/**
 * @method
 * @name getCurrentDate
 * @description desc
 * @param
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.getCurrentDate = function() {
    var d = new Date();
    var curDate = '';
    curDate += d.getFullYear();
    curDate += d.getMonth() + 1;
    curDate += d.getDate();
    return curDate;
};


/*
 * 전화번호 숫자 체크 함수
 */
/**
 * @method
 * @name fn_checkPhoneNumber
 * @description desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkPhoneNumber = function(id) {
    var pHome = "/^0\\d{8,9}$/g";
    var pGeneral = "/^0\\d{8,10}$/g";
    phoneNum = id.getValue();
    phoneNum = phoneNum.replace(/[-\s]+/g, "");
    if (pHome.test(phoneNum) || pGeneral.test(phoneNum)) return true;

    else {
        alert('[' + id.id + '] 항목의 전화번호 형식이 맞지 않습니다.');
        return false;
    }
};



/*
 * 이메일 형식 체크 함수
 */
/**
 * @method
 * @name fn_checkEmail
 * @description desc
 * @param {string} id desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkEmail = function(id) {
    email = id.getValue();
    var mailexp = /^[a-z][\w.-]+@\w[\w.-]+\.[\w.-]*[a-z][a-z]$/i;
    if (mailexp.test(email)) return true;

    else {
        alert('[' + id.id + '] 항목의 이메일 형식이 맞지 않습니다.');
        return false;
    }
};



/********************************************** 
 * 함수명   : fn_getAsciiLength
 * @param str - 문자열
 * 설명     : 문자열 길이를 check한다.
 ***********************************************/
/**
 * @method
 * @name fn_getAsciiLength
 * @description desc
 * @param {string} str desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_getAsciiLength = function(str) {
    var len;
    var temp;
    len = str.length;
    var tot_cnt = 0;
    for (var k = 0; k < len; k++) {
        temp = str.charAt(k);
        if (escape(temp).length > 4) tot_cnt += 2;

        else tot_cnt++;
    }
    return tot_cnt++;
};
/**
 * @method
 * @name fn_checkLength
 * @description desc
 * @param {string} id desc
 * @param {string} limitLength desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkLength = function(id, limitLength) {
    var length = scwin.fn_getAsciiLength(id.getValue());
    if (length > limitLength) {
        alert('[' + id.id + '] 항목이 제한길이 ' + limitLength + 'Byte를 초과했습니다. (한글 1글자 2Byte, 영문 1글자 1Byte)');
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_checkNumber
 * @description desc
 * @param {string} id desc
 * @param {string} positiveYn desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkNumber = function(id, positiveYn) {
    var num = id.getValue();
    if (isNaN(num)) {
        alert('[' + id.id + '] 항목은 숫자를 입력해야 합니다.');
        return false;
    }
    if (positiveYn == 'Y' && num < 0) {
        alert('[' + id.id + '] 항목은 양수 숫자만 입력해야 합니다.');
        return false;
    }
    return true;
};
/**
 * @method
 * @name fn_checkDate
 * @description desc
 * @param {string} id desc
 * @param {string} format desc
 * @returns
 * @hidden N
 * @exception
 * @example
 */
scwin.fn_checkDate = function(id, format) {
    try {
        var param = id.getValue();
        param = param.replace(/-/g, '');
        var year, month, day;
        if (format == 'YM') {
            // 자리수가 맞지않을때
            if (isNaN(param) || param.length != 6) {
                alert('[' + id.id + '] 항목은 년월 6자리를 입력해야 합니다.');
                return false;
            }
            year = Number(param.substring(0, 4));
            month = Number(param.substring(4, 6));
            if (month < 1 || month > 12) {
                alert('[' + id.id + '] 항목의 년월 형식이 맞지 않습니다.');
                return false;
            }
        } else if (format == 'YMD') {
            if (isNaN(param) || param.length != 8) {
                alert('[' + id.id + '] 항목은 년월일 8자리를 입력해야 합니다.');
                return false;
            }
            year = Number(param.substring(0, 4));
            month = Number(param.substring(4, 6));
            day = Number(param.substring(6, 8));

            //var dd = day / 0;

            if (month < 1 || month > 12) {
                alert('[' + id.id + '] 항목의 형식이 맞지 않습니다.');
                return false;
            }
            var maxDaysInMonth = [31, 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
            var maxDay = maxDaysInMonth[month - 1];

            // 윤년 체크
            if (month == 2 && (year % 4 == 0 && year % 100 != 0 || year % 400 == 0)) {
                maxDay = 29;
            }
            if (day <= 0 || day > maxDay) {
                alert('[' + id.id + '] 항목의 형식이 맞지 않습니다.');
                return false;
            }
        }
        return true;
    } catch (err) {
        return false;
    }
};
